CREATE TABLE `ShopApplication` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`city` VARCHAR(191) NOT NULL,`address` VARCHAR(191) NOT NULL,`phone` VARCHAR(191) NOT NULL,`details` VARCHAR(191) NOT NULL,`state` VARCHAR(191) NOT NULL DEFAULT 'PENDING',`reviewReason` VARCHAR(191) NOT NULL DEFAULT '',`reviewedBy` VARCHAR(191) NULL,`reviewedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE INDEX `ShopApplication_userId_key`(`userId`),INDEX `ShopApplication_state_createdAt_idx`(`state`,`createdAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
